package com.asmj.marketplace.product.controller;import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.product.dto.ProductDtos.CouponRequest;import com.asmj.marketplace.product.service.ProductService;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;
@RestController @PreAuthorize("hasRole('ADMIN')") @RequestMapping("/api/admin/products") @RequiredArgsConstructor public class ProductAdminController{final ProductService s;@GetMapping public ApiResponse<?> all(){return ApiResponse.ok("",s.all());}@PutMapping("/{id}/approval")public ApiResponse<?> approval(@PathVariable String id,@RequestParam boolean approved){return ApiResponse.ok("",s.adminApprove(id,approved));}@GetMapping("/orders")public ApiResponse<?> orders(){return ApiResponse.ok("",s.allOrders());}@GetMapping("/coupons")public ApiResponse<?> coupons(){return ApiResponse.ok("",s.coupons());}@PostMapping("/coupons")public ApiResponse<?> coupon(@RequestBody CouponRequest r){return ApiResponse.ok("",s.saveCoupon(r));}}
